# Tile grid for the painted town: 1200x896 px each at 4.8 px per world unit (250 x 186.67 units).
PPU=4.8; TW=250; TH=896/PPU
COLS=[-150,50]; ROWS=[-455,-305,-155]
def tile(r,c): return COLS[c],ROWS[r],COLS[c]+TW,ROWS[r]+TH
